size_t encode_telemetry(uint8_t *buf, size_t cap, uint32_t mv, int32_t temp_c) {
    SYN_CborWriter w;
    syn_cbor_writer_init(&amp;w, buf, cap);
    syn_cbor_write_map_begin(&amp;w, 2);
    syn_cbor_write_text_cstr(&amp;w, "mv");
    syn_cbor_write_uint(&amp;w, mv);
    syn_cbor_write_text_cstr(&amp;w, "tc");
    syn_cbor_write_int(&amp;w, temp_c);
    return syn_cbor_writer_ok(&amp;w) ? syn_cbor_writer_len(&amp;w) : 0U;
}
</code></pre>

Module Header Config Task <code>sched/syn_task.h</code> <code>SYN_USE_SCHED</code> Scheduler <code>sched/syn_sched.h</code> <code>SYN_USE_SCHED</code> Mutex <code>sched/syn_mutex.h</code> <code>SYN_USE_MUTEX</code> <p>The scheduler manages a caller-owned array of <code>SYN_Task</code> descriptors. Each call to <code>syn_sched_run()</code> dispatches one eligible task using ranked selection with per-priority starvation bounds and round-robin rotation within each priority level.</p> <pre><code>static SYN_Task tasks[3];
static SYN_Sched sched;

syn_task_create(&amp;tasks[0], "blink",   blink_fn,   SYN_PRIO_HIGH,     NULL);
syn_task_create(&amp;tasks[1], "serial",  serial_fn,  SYN_PRIO_CRITICAL, NULL);
syn_task_create(&amp;tasks[2], "monitor", monitor_fn, SYN_PRIO_NORMAL,   NULL);

syn_sched_init(&amp;sched, tasks, 3);
syn_sched_run_forever(&amp;sched);  // never returns
</code></pre>
